    memset(long_filename, 'a', 511);
    long_filename[511] = '\0';

    char content_type[] = "text/plain";

    // This should trigger a buffer overflow if the function doesn't check bounds
    int result = set_file_metadata(&meta, long_filename, content_type);

    printf("Stack buffer overflow test completed with result: %d\n", result);
}

void test_buffer_overflow_heap() {
    struct file_metadata *meta = malloc(sizeof(struct file_metadata));
    if (meta == NULL) {
        printf("Failed to allocate memory\n");
        return;
    }

    // Create a content type that exceeds the buffer size
    char filename[] = "test.txt";
    char long_content_type[128];
    memset(long_content_type, 'b', 127);
    long_content_type[127] = '\0';

    // This should trigger a buffer overflow if the function doesn't check bounds
    int result = set_file_metadata(meta, filename, long_content_type);

    printf("Heap buffer overflow test completed with result: %d\n", result);

    free(meta);
}

void test_boundary_conditions() {
    struct file_metadata meta;

    // Test with exactly the boundary length for filename (255 chars + null terminator)
    char boundary_filename[256];
    memset(boundary_filename, 'c', 255);
    boundary_filename[255] = '\0';

    // Test with exactly the boundary length for content_type (63 chars + null terminator)
