    memset(boundary_content_type, 'd', 63);
    boundary_content_type[63] = '\0';

    int result = set_file_metadata(&meta, boundary_filename, boundary_content_type);

    printf("Boundary conditions test completed with result: %d\n", result);
}

int main() {
    printf("Starting security tests...\n");

    test_buffer_overflow_stack();
